    // --- 核心函数 (SafeGetValue 修正版) ---
    const SafeGetValue = (obj, path, defaultValue) => {
        try {
            const keys = path.split('.'); let current = obj;
            for (let i = 0; i < keys.length; i++) {
                const key = keys[i]; if (current === null || typeof current !== 'object') { return defaultValue; }
                const match = key.match(/^(.+?)\[(\d+)\]$/); // V2.6 Correct Regex Literal
                if (match) {
                    const arrayKey = match[1]; const index = parseInt(match[2], 10);
                    if (current.hasOwnProperty(arrayKey) && Array.isArray(current[arrayKey]) && index >= 0 && index < current[arrayKey].length) { current = current[arrayKey][index]; }
                    else { return defaultValue; }
                } else if (current.hasOwnProperty(key)) { current = current[key]; }
                else { return defaultValue; }
            } return current === undefined ? defaultValue : current;
        } catch (error) { console.error(`SafeGetValue CRITICAL ERROR for path \"${path}\" in obj:`, obj, 'Error:', error); return defaultValue; }
