        const hp = SafeGetValue(resources, '生命值[0]', 0); const maxHp = SafeGetValue(resources, '生命值上限[0]', 1); const mp = SafeGetValue(resources, '法力值[0]', 0); const maxMp = SafeGetValue(resources, '法力值上限[0]', 1); const sp = SafeGetValue(resources, '体力值[0]', 0); const maxSp = SafeGetValue(resources, '体力值上限[0]', 1);
