    // --- [修改 V4.4] 简化的事件监听器 ---
    document.addEventListener('click', function(event) {
        const target = event.target;

        // --- Handlers for Status UI ---
        const filterBtn = target.closest('.filter-btn[data-filter-type]');
        if (filterBtn) {
            const filterType = filterBtn.dataset.filterType;
            const filterValue = filterBtn.dataset.filterValue;
            if (filterType === 'inventory') {
                currentInventoryFilter = filterValue;
                populateAssets(SafeGetValue(window.last_stat_data, '财产', {}));
            }
            return;
        }

        const actionTargetNonCombat = target.closest('[data-action]');
        if (actionTargetNonCombat) {
            const action = actionTargetNonCombat.dataset.action;
            const location = actionTargetNonCombat.dataset.location;
            const itemNameNonCombat = actionTargetNonCombat.dataset.itemName;

            if (action === 'travel' && location) { sendCommand(`/send 前往 ${location} |/trigger`); }
            else if (action === 'update-news') { sendCommand(`/send 更新\"每日新闻\" |/trigger`); }
            // [移除] 战斗相关的 action (use-skill, attack, etc.)
            // 保留非战斗的 use-item (如果需要的话)
            else if (action === 'use-item' && itemNameNonCombat) { 
                // 确保我们不在战斗中
                const statusContainerVisible = !document.getElementById('status-container-wrapper')?.classList.contains('hidden');
                if (statusContainerVisible) {
                    sendCommand(`/send 使用 ${itemNameNonCombat} |/trigger`);
                }
            }
        }

        const protagonistTab = target.closest('.protagonist-tab[data-tab]');
        if (protagonistTab) {
            const newTab = protagonistTab.dataset.tab;
            if (newTab !== currentProtagonistTab) {
                currentProtagonistTab = newTab;
                populateProtagonist(SafeGetValue(window.last_stat_data, '主角', {}));
            }
            return;
        }
    });


