                customCosts: { race: 80, identity: 60, equipment: 50, item: 30, skill: 60, redThread: 300 }
            };
            const elements = {
                reincarnationPointsDisplay:document.getElementById("reincarnationPointsDisplay"), pastLifeInput:document.getElementById("pastLifeInput"), legacyDescription:document.getElementById("legacyDescription"), nameInput:document.getElementById("nameInput"), genderInput:document.getElementById("genderInput"), customGenderInput:document.getElementById("customGenderInput"), ageInput:document.getElementById("ageInput"), raceInput:document.getElementById("raceInput"), customRaceInput:document.getElementById("customRaceInput"), identityInput:document.getElementById("identityInput"), customIdentityInput:document.getElementById("customIdentityInput"), startLocationInput:document.getElementById("startLocationInput"), originVignette:document.getElementById("originVignette"), attributesContainer:document.querySelector(".attributes-container"), apDisplay:document.getElementById("apDisplay"), relationshipGroup:document.getElementById("relationshipGroup"), relationshipInput:document.getElementById("relationshipInput"), relationshipVignette:document.getElementById("relationshipVignette"), backgroundsSummary:document.getElementById("backgroundsSummary"), backgroundStoryGroup:document.getElementById("backgroundStoryGroup"), backgroundStory:document.getElementById("backgroundStory"), imperialState:document.getElementById("imperialState"), imperialStateLabel:document.getElementById("imperialStateLabel"), abyssalState:document.getElementById("abyssalState"), abyssalStateLabel:document.getElementById("abyssalStateLabel"), worldStateCost:document.getElementById("worldStateCost"), lilithModeInput:document.getElementById("lilithModeInput"), destinyPointsFinal:document.getElementById("destinyPointsFinal"), sendButton:document.getElementById("sendButton"), modal:document.getElementById("selectionModal"), modalTitle:document.getElementById("modalTitle"), modalOptionsList:document.getElementById("modalOptionsList"), modalConfirmBtn:document.getElementById("modalConfirmBtn"), closeBtn:document.querySelector(".close-btn")
            };
            let selections = { equipments:[], items:[], skills:[], negativeTraits:[], redThreads:[], backgrounds:[], custom:{} };
            let attributePoints = {};
            const attributes = ['力量','敏捷','体质','智力','精神'];
            let currentOpenCategory = '';

            function init() {
                // Populate static dropdowns
                DATA.pastLives.forEach(pl => elements.pastLifeInput.add(new Option(`${pl.name} (${pl.points}点)`, pl.id)));
                DATA.races.forEach(r => { const opt = new Option(`${r.id} (-${r.cost}点)`, r.id); opt.dataset.cost = r.cost; elements.raceInput.add(opt); });
                elements.raceInput.add(new Option(`自定义 (-${DATA.customCosts.race}点)`, 'custom'));
                DATA.lilithModes.forEach(m => { const opt = new Option(`${m.name} (-${m.cost}点)`, m.name); opt.dataset.cost = m.cost; elements.lilithModeInput.add(opt);});

                renderAttributeControls();
                addEventListeners();
                updateAll();
            }

            function updateAll() {
                const legacy = DATA.pastLives.find(p => p.id === elements.pastLifeInput.value)?.legacy;
                elements.legacyDescription.textContent = legacy || '';
                updateIdentityOptions();
                updateVignettes();
                calculatePoints();
            }

            function addEventListeners() {
                document.querySelectorAll('.stage-btn[data-target]').forEach(btn => btn.addEventListener('click', (e) => switchStage(e.target.dataset.target)));
                ['pastLifeInput', 'raceInput', 'identityInput', 'startLocationInput', 'relationshipInput', 'lilithModeInput'].forEach(id => elements[id].addEventListener('change', updateAll));
                ['customGenderInput', 'customRaceInput', 'customIdentityInput', 'backgroundStory'].forEach(id => elements[id].addEventListener('input', calculatePoints));

                elements.genderInput.addEventListener('change', () => elements.customGenderInput.classList.toggle('show', elements.genderInput.value === 'custom'));
                elements.raceInput.addEventListener('change', () => {
                    elements.customRaceInput.classList.toggle('show', elements.raceInput.value === 'custom');
                    selections.identity = [];
                });
                elements.identityInput.addEventListener('change', () => {
                    elements.customIdentityInput.classList.toggle('show', elements.identityInput.value === 'custom');
                });

                [elements.imperialState, elements.abyssalState].forEach(slider => slider.addEventListener('input', () => {
                    const iLabels = {'-20':'帝国衰微','0':'秩序井然','20':'帝国鼎盛'}, aLabels = {'-15':'深渊沉睡','0':'暗流涌动','15':'深渊入侵'};
                    elements.imperialStateLabel.textContent = iLabels[elements.imperialState.value];
                    elements.abyssalStateLabel.textContent = aLabels[elements.abyssalState.value];
                    calculatePoints();
                }));

                document.querySelectorAll('.selection-btn').forEach(btn => btn.addEventListener('click', () => openModal(btn.dataset.category)));
                elements.modalConfirmBtn.addEventListener('click', handleModalConfirm);
                elements.closeBtn.addEventListener('click', closeModal);
                window.addEventListener('click', e => { if (e.target === elements.modal) closeModal(); });
                elements.sendButton.addEventListener('click', generateOutput);
            }

            function updateIdentityOptions() {
                const race = DATA.races.find(r => r.id === elements.raceInput.value);
                const currentVal = elements.identityInput.value;
                elements.identityInput.innerHTML = `<option value="" disabled selected>选择身份</option>`;
                if (race) {
                    race.identities.forEach(id => {
                        const idData = DATA.identities[id];
                        const cost = idData.cost >= 0 ? `-${idData.cost}` : `+${-idData.cost}`;
                        const opt = new Option(`${idData.name} (${cost}点)`, id); opt.dataset.cost = idData.cost; elements.identityInput.add(opt);
                    });
                }
                const customOpt = new Option(`自定义 (-${DATA.customCosts.identity}点)`, 'custom'); customOpt.dataset.cost = DATA.customCosts.identity; elements.identityInput.add(customOpt);
                elements.identityInput.value = Array.from(elements.identityInput.options).some(o => o.value === currentVal) ? currentVal : "";
                updateLocationOptions();
            }

            function updateLocationOptions() {
                const identity = DATA.identities[elements.identityInput.value];
                const currentVal = elements.startLocationInput.value;
                elements.startLocationInput.innerHTML = `<option value="" disabled selected>选择地点</option>`;
                if (!identity) { calculatePoints(); return; }
                identity.locations.forEach(id => {
                    const locData = DATA.locations[id];
                    const cost = locData.cost >= 0 ? `-${locData.cost}` : `+${-locData.cost}`;
                    const opt = new Option(`${locData.name || id} (${cost}点)`, id); opt.dataset.cost = locData.cost; elements.startLocationInput.add(opt);
                });
                elements.startLocationInput.value = Array.from(elements.startLocationInput.options).some(o => o.value === currentVal) ? currentVal : "";
            }

            function updateRelationshipOptions() {
                const partnerName = selections.redThreads[0];
                elements.relationshipGroup.classList.toggle('show', !!partnerName);
                if (partnerName && DATA.relationships[partnerName]) {
                    const currentVal = elements.relationshipInput.value;
                    elements.relationshipInput.innerHTML = '';
                    DATA.relationships[partnerName].forEach(rel => {
                        const costText = rel.cost > 0 ? `-${rel.cost}点` : rel.cost < 0 ? `+${-rel.cost}点` : '0点';
                        const opt = new Option(`${rel.name} (${costText})`, rel.name); opt.dataset.cost = rel.cost; elements.relationshipInput.add(opt);
                    });
                    elements.relationshipInput.value = Array.from(elements.relationshipInput.options).some(o => o.value === currentVal) ? DATA.relationships[partnerName][0].name : "";
                }
            }

            function updateVignettes() {
                const identity = DATA.identities[elements.identityInput.value];
                elements.originVignette.style.display = (identity && identity.vignette) ? 'block' : 'none';
                if (identity && identity.vignette) elements.originVignette.textContent = identity.vignette;
                const relationship = DATA.relationships[selections.redThreads[0]]?.find(r => r.name === elements.relationshipInput.value);
                elements.relationshipVignette.style.display = (relationship && relationship.vignette) ? 'block' : 'none';
                if (relationship && relationship.vignette) elements.relationshipVignette.textContent = relationship.vignette;
            }

            function openModal(category) { currentOpenCategory = category; elements.modal.style.display = 'block'; populateModal(category); }
            function closeModal() { elements.modal.style.display = 'none'; }

            function populateModal(category) {
                const isRadio = ['redThreads', 'backgrounds'].includes(category);
                const data = DATA[category];
                const titles = {'equipments':'装备','items':'物品','skills':'技能','negativeTraits':'负面特质','redThreads':'伙伴','backgrounds':'背景'};
                elements.modalTitle.textContent = `选择${titles[category]}`;
                elements.modalOptionsList.innerHTML = '';

                data.forEach(item => {
                    const isChecked = selections[category].includes(item.name);
                    const costText = category === 'negativeTraits' ? `| +${item.points}点` : (item.cost ? `| -${item.cost}点` : '');
                    const rarity = RARITY_MAP[item.rarity] || '';
                    const el = document.createElement('label');
                    el.className = 'skill-option';
                    el.innerHTML = `<input type="${isRadio ? 'radio':'checkbox'}" name="${category}" value="${item.name}" ${isChecked ? 'checked':''}>
                        <div class="skill-option-content">
                            <span class="skill-main-info"><span class="rarity-${item.rarity}">【${rarity}】</span> ${item.name} ${costText}</span>
                            <small class="skill-description">${item.description}</small>
                        </div>`;
                    elements.modalOptionsList.appendChild(el);
                });

                if (Object.keys(DATA.customCosts).includes(category.slice(0, -1))) {
                    const cat_single = category.slice(0, -1);
                    const customCost = DATA.customCosts[cat_single];
                    const customEl = document.createElement('div');
                    customEl.className = 'modal-custom-section';
                    customEl.innerHTML = `<label for="custom-${category}">自定义 (-${customCost}点)</label><textarea id="custom-${category}" rows="3" placeholder="请详细描述...">${selections.custom[cat_single] || ''}</textarea>`;
                    elements.modalOptionsList.appendChild(customEl);
                }
            }

            function handleModalConfirm() {
                const cat = currentOpenCategory;
                selections[cat] = Array.from(elements.modalOptionsList.querySelectorAll(`input[name="${cat}"]:checked`)).map(i => i.value);
                const customTextarea = document.getElementById(`custom-${cat}`);
                if (customTextarea) selections.custom[cat.slice(0,-1)] = customTextarea.value.trim();
                if(cat === 'redThreads') updateRelationshipOptions();
                if(cat === 'backgrounds') elements.backgroundStoryGroup.classList.toggle('show', selections.backgrounds[0] === '【自定义背景】');
                updateSelectionSummary(cat);
                updateAll();
                closeModal();
            }

            function updateSelectionSummary(category) {
                const summaryEl = document.getElementById(`${category}Summary`);
                if (!summaryEl) return;
                let cost = 0, gain = 0, count = selections[category].length;
                const cat_single = category.slice(0,-1);
                selections[category].forEach(name => {
                    const item = DATA[category].find(i => i.name === name);
                    if(item) { if (category === 'negativeTraits') gain += item.points; else cost += item.cost; }
                });
                let customText = '';
                if (selections.custom[cat_single]) {
                    count++;
                    cost += DATA.customCosts[cat_single];
                    customText = ' (含自定义)';
                }
                if (category === 'negativeTraits') summaryEl.textContent = `已选${count}项，获得${gain}点${customText}`;
                else if (['redThreads', 'backgrounds'].includes(category)) summaryEl.textContent = count > 0 ? `已选: ${selections[category][0]}${customText}` : '未选择';
                else summaryEl.textContent = `已选${count}项，消耗${cost}点${customText}`;
            }

            function calculatePoints() {
                const getSelectedData = (el) => el.options[el.selectedIndex];
                let basePoints = parseInt(DATA.pastLives.find(p => p.id === elements.pastLifeInput.value)?.points) || 0;
                let cost = 0;

                cost += elements.raceInput.value === 'custom' ? DATA.customCosts.race : (DATA.races.find(r => r.id === elements.raceInput.value)?.cost || 0);
                cost += elements.identityInput.value === 'custom' ? DATA.customCosts.identity : (DATA.identities[elements.identityInput.value]?.cost || 0);
                cost += parseInt(getSelectedData(elements.startLocationInput)?.dataset.cost) || 0;
                cost += DATA.lilithModes.find(m => m.name === elements.lilithModeInput.value)?.cost || 0;
                cost += DATA.relationships[selections.redThreads[0]]?.find(r => r.name === elements.relationshipInput.value)?.cost || 0;

                ['equipments', 'items', 'skills', 'redThreads', 'negativeTraits'].forEach(cat => {
                    (selections[cat] || []).forEach(name => {
                        const item = DATA[cat].find(i => i.name === name);
                        if(item) cost += (cat === 'negativeTraits' ? -item.points : item.cost);
                    });
                });
                Object.entries(selections.custom).forEach(([cat, val]) => { if (val) cost += DATA.customCosts[cat] || 0; });

                const worldStateCost = parseInt(elements.imperialState.value) + parseInt(elements.abyssalState.value);
                elements.worldStateCost.textContent = worldStateCost >= 0 ? `+${worldStateCost}` : worldStateCost;
                cost -= worldStateCost;

                currentReincarnationPoints = basePoints - cost;
                elements.reincarnationPointsDisplay.textContent = currentReincarnationPoints;
                elements.reincarnationPointsDisplay.parentElement.style.color = currentReincarnationPoints < 0 ? '#ff0000' : 'var(--points-color)';
                elements.destinyPointsFinal.textContent = Math.max(0, currentReincarnationPoints) * 10;
            }

            function renderAttributeControls() {
                elements.attributesContainer.innerHTML = '';
                attributes.forEach(attr => {
                    attributePoints[attr] = 0;
                    elements.attributesContainer.insertAdjacentHTML('beforeend', `<div class="attribute-control" data-attr="${attr}"><span class="stat-name">${attr}</span><span class="stat-value">4</span><div class="ap-buttons"><button class="ap-btn minus">-</button><input type="number" class="ap-input" value="0" readonly><button class="ap-btn plus">+</button></div></div>`);
                });
                document.querySelectorAll('.ap-btn').forEach(btn => btn.addEventListener('click', e => {
                    const control = e.target.closest('.attribute-control');
                    const stat = control.dataset.attr;
                    const isPlus = e.target.classList.contains('plus');
                    const totalAllocated = Object.values(attributePoints).reduce((s,p)=>s+p, 0);
                    if(isPlus && totalAllocated < 5) attributePoints[stat]++;
                    else if(!isPlus && attributePoints[stat] > 0) attributePoints[stat]--;
                    updateAttributes();
                }));
                 updateAttributes();
            }

            function updateAttributes() {
                const totalAllocated = Object.values(attributePoints).reduce((s,p)=>s+p, 0);
                elements.apDisplay.textContent = 5 - totalAllocated;
                attributes.forEach(attr => {
                    const row = document.querySelector(`[data-attr="${attr}"]`);
                    row.querySelector('.stat-value').textContent = 4 + attributePoints[attr];
                    row.querySelector('.ap-input').value = attributePoints[attr];
                    row.querySelector('.plus').disabled = totalAllocated >= 5;
                    row.querySelector('.minus').disabled = attributePoints[attr] <= 0;
                });
            }

            function generateOutput() {
                if (currentReincarnationPoints < 0) { alert(`转生点不足！请重新调整你的选择。`); return; }
                const getVal = (el, customEl) => el.value === 'custom' ? customEl.value.trim() : el.value;
                const formatModal = (cat) => {
                    let text = selections[cat].join(', ');
                    const s_cat = cat.slice(0,-1);
                    if (selections.custom[s_cat]) text += (text ? ', ' : '') + `自定义: ${selections.custom[s_cat]}`;
                    return text || '无';
                };
                const finalDestinyPoints = Math.max(0, currentReincarnationPoints) * 10;
                let message = `[角色卡]\n`
                + `前世: ${DATA.pastLives.find(p=>p.id===elements.pastLifeInput.value).name}\n`
                + `遗泽: ${elements.legacyDescription.textContent}\n\n`
                + `姓名: ${elements.nameInput.value||'无名者'}\n`
                + `性别: ${getVal(elements.genderInput, elements.customGenderInput)}\n`
                + `年龄: ${elements.ageInput.value}\n`
                + `种族: ${getVal(elements.raceInput, elements.customRaceInput)}\n`
                + `身份: ${getVal(elements.identityInput, elements.customIdentityInput)}\n`
                + `起点: ${elements.startLocationInput.value}\n\n`
                + `属性: (力量:${4+attributePoints['力量']}, 敏捷:${4+attributePoints['敏捷']}, 体质:${4+attributePoints['体质']}, 智力:${4+attributePoints['智力']}, 精神:${4+attributePoints['精神']})\n\n`
                + `世界状态: (帝国: ${elements.imperialStateLabel.textContent}, 深渊: ${elements.abyssalStateLabel.textContent})\n`
                + `莉莉丝模式: ${elements.lilithModeInput.value}\n`
                + `命运点数: ${finalDestinyPoints}\n\n`
                + `--- 详情 ---\n`
                + `背景: ${formatModal('backgrounds')}\n`
                + `背景故事: ${selections.backgrounds[0] === '【自定义背景】' ? elements.backgroundStory.value : '无'}\n`
                + `负面特质: ${formatModal('negativeTraits')}\n`
                + `初始伙伴: ${selections.redThreads.length>0 ? formatModal('redThreads') : '无'} (关系: ${elements.relationshipInput.value || '默认'})\n`
                + `装备: ${formatModal('equipments')}\n`
                + `物品: ${formatModal('items')}\n`
                + `技能: ${formatModal('skills')}\n`;

                if (typeof triggerSlash !== 'undefined') { triggerSlash(`/send ${message}`); } 
                else { console.log(message); alert('角色卡已生成，请在浏览器控制台(F12)查看。'); }
            }
            init();
        });
    </script>
</body>
