// [Kora注]: 以下是一个完整的、即用型的酒馆助手脚本。
// 它将动态地在AI的回复中，找到一个占位符 <StatusPlaceHolderImpl/>，并将其替换为您设计的、已填满数据的完整UI面板。

(async function() {
    // ----------------------------------------------------------------------------------
    // 步骤一：定义核心占位符
    // ----------------------------------------------------------------------------------
    // 这个正则表达式用于在AI的回复中，查找我们将要替换的UI占位符。
    const statusblock_regex = /<StatusPlaceHolderImpl\/>/s;

    // ----------------------------------------------------------------------------------
    // 步骤二：核心渲染函数 (generateStatusBlock)
    // ----------------------------------------------------------------------------------
    // Kora注：这是整个脚本的心脏。它接收从后台获取的`variables`对象(包含stat_data)，
    // 然后在前端动态地创建出整个UI面板的HTML结构，并将其作为一个字符串返回。
    function generateStatusBlock(variables) {
        // 安全地获取 stat_data，如果不存在则使用空对象
        const data = variables.stat_data || {};

        // 헬퍼 함수 (Helper Functions)
        const SafeGetValue = (obj, path, defaultValue = '') => {
            const value = _.get(obj, path, defaultValue);
            if (Array.isArray(value)) {
                return value[0] !== undefined ? value[0] : defaultValue;
            }
            return value;
        };

        const renderProgressBar = (current, max, color) => {
            const percentage = (current / max) * 100;
            return `<div class="progress-bar-container"><div class="progress-bar-value" style="width: ${percentage}%; background-color: ${color};"></div></div>`;
        };

        // 动态生成红线对象HTML
        const renderDestinyTargets = () => {
            const targets = SafeGetValue(data, '命运系统.红线对象', {});
            let html = '';
            // 过滤掉 $meta 键
            const characterKeys = Object.keys(targets).filter(key => key !== '$meta');

            if (characterKeys.length === 0) {
                return '<p id="no-destiny-targets-msg">（尚未与任何人缔结深刻的命运联系）</p>';
            }

            for (const key of characterKeys) {
                const char = targets[key];
                const name = SafeGetValue(char, '姓名', key);
                const level = SafeGetValue(char, '等级', '未知');
                const personality = SafeGetValue(char, '性格', '未知');
                const affectionRaw = SafeGetValue(char, '好感度', '0/1000');
                const [currentAff, maxAff] = affectionRaw.split('/').map(Number);
                const measurements = SafeGetValue(char, '三围', '未知');
                const attire = SafeGetValue(char, '衣着', '未知');
                const appearance = SafeGetValue(char, '外貌', '未知');
                const feet = SafeGetValue(char, '玉足', '未知');
                const evaluation = SafeGetValue(char, '评价', '无');

                html += `
                <details class="destiny-target">
                    <summary>${name}<span class="arrow-toggle">▼</span></summary>
                    <div class="destiny-target-content">
                        <div class="property"><span class="property-name">姓名:</span> <span class="value-main">${name}</span></div>
                        <div class="property"><span class="property-name">等级:</span> <span class="value-main">${level}</span></div>
                        <div class="property"><span class="property-name">性格:</span> <span class="value-main">${personality}</span></div>
                        <div class="property"><span class="property-name">好感度:</span> <span class="value-main">${affectionRaw}</span></div>
                        ${renderProgressBar(currentAff, maxAff, '#EC407A')}
                        <div class="property"><span class="property-name">三围:</span> <span class="value-main">${measurements}</span></div>
                        <div class="property"><span class="property-name">衣着:</span> <span class="value-main">${attire}</span></div>
                        <div class="property"><span class="property-name">外貌:</span> <span class="value-main">${appearance}</span></div>
                        <div class="property"><span class="property-name">玉足:</span> <span class="value-main">${feet}</span></div>
                        <div class="property"><span class="property-name">评价:</span> <span class="value-main">${evaluation}</span></div>
                    </div>
                </details>
                `;
            }
            return html;
        };

        // 动态生成新闻HTML
        const renderNews = () => {
            const news = SafeGetValue(data, '新闻系统', {});
            const processNewsArray = (arr) => Array.isArray(arr) ? arr.filter(item => item !== '$__META_EXTENSIBLE__$').join('<br>') : '（无）';

            return `
                <details class="sub-section" open>
                    <summary><span class="news-headline news-gold-lion">🦁 金狮快讯</span><span class="arrow-toggle">▼</span></summary>
                    <div class="sub-section-content"><p>${processNewsArray(SafeGetValue(news, '金狮快讯', [])[0]) || '（暂无最新快讯）'}</p></div>
                </details>
                <details class="sub-section" open>
                    <summary><span class="news-headline news-tavern">🍻 酒馆留言板</span><span class="arrow-toggle">▼</span></summary>
                    <div class="sub-section-content"><p>${processNewsArray(SafeGetValue(news, '酒馆留言板', [])[0]) || '（留言板上空空如也）'}</p></div>
                </details>
                <details class="sub-section" open>
                    <summary><span class="news-headline news-wonders">🦄 世界真奇妙</span><span class="arrow-toggle">▼</span></summary>
                    <div class="sub-section-content"><p>${processNewsArray(SafeGetValue(news, '世界真奇妙', [])[0]) || '（今天世界平平无奇）'}</p></div>
                </details>
                <details class="sub-section" open>
                    <summary><span class="news-headline news-tea-party">☕ 莉莉丝的午后茶会</span><span class="arrow-toggle">▼</span></summary>
                    <div class="sub-section-content"><p>${processNewsArray(SafeGetValue(news, '莉莉丝的午后茶会', [])[0]) || '（茶会上没什么新八卦）'}</p></div>
                </details>
            `;
        };

        // 完整的HTML结构模板
        // Kora注：我们将CSS和必要的交互JS直接内联到HTML中，使其成为一个独立的、无需外部依赖的组件。
        return `
        <div id="kora-status-panel-${new Date().getTime()}">
            <style>
                /* Kora注：此处内联您提供的全部CSS样式 */
                @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;700&family=Merriweather:ital,wght@0,400;0,700;1,400&family=Noto+Sans+SC:wght@400;500;700&display=swap');
                #kora-status-panel-${new Date().getTime()} body{font-family:'Noto Sans SC','Merriweather',serif;background-color:#f5efe6;color:#4a3b31;margin:0;padding:15px;background-repeat:repeat}.status-scroll{border:2px solid #785a4e;border-radius:8px;padding:20px;background-color:rgba(240,230,210,.85);box-shadow:0 4px 12px rgba(0,0,0,.2);max-width:900px;margin:auto}.time-location-box{background-color:#e8ddcb;padding:10px 15px;border-radius:4px;margin-bottom:15px;border:1px solid #c6b8a5;text-align:left}.time-location-box p{margin:5px 0;font-size:.95em;font-family:'Noto Sans SC','Courier New',monospace}.value-main{font-weight:500;font-family:'Noto Sans SC','Courier New',monospace}details.section,details.sub-section,details.destiny-target{margin-bottom:10px;border:1px solid #d3c5b3;border-radius:4px;overflow:hidden}details>summary{font-family:'Cinzel',serif;font-weight:700;color:#5d4037;background-color:#d7c8b6;padding:10px 15px;cursor:pointer;list-style:none;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #c6b8a5;text-align:left}details>summary::-webkit-details-marker{display:none}.arrow-toggle{transition:transform .2s}details[open]>summary .arrow-toggle{transform:rotate(90deg)}.section-content,.sub-section-content,.destiny-target-content{padding:15px;background-color:rgba(253,250,245,.9);text-align:left;font-size:.9em}.property{margin-bottom:8px;line-height:1.6}.property-name{font-weight:700;color:#6a514d}.progress-bar-container{background-color:#c8bbaf;border-radius:5px;height:18px;margin-top:4px;margin-bottom:8px;overflow:hidden;border:1px solid #b3a291}.progress-bar-value{height:100%;width:0;transition:width .5s ease-in-out;text-align:center;color:#fff;font-size:.8em;line-height:18px;font-weight:700}.thin-divider{border:0;border-top:1px dashed #b3a291;margin:10px 0}.news-headline{font-weight:700}.news-gold-lion{font-family:'Cinzel',serif;color:#b9892d}.news-tavern{font-family:'Merriweather',serif;color:#6d4c41}.news-wonders{font-family:'Merriweather',serif;font-style:italic;color:#5c6bc0}.news-tea-party{font-family:'Cinzel',serif;color:#c2185b}
            </style>

            <div class="status-scroll">
                <div class="time-location-box">
                    <p>⏳️ 时间: <span class="value-main">${SafeGetValue(data, '世界状态.时间', '未知')}</span></p>
                    <p>📍 地点: <span class="value-main">${SafeGetValue(data, '世界状态.地点', '未知')}</span></p>
                </div>

                <details class="section" open>
                    <summary>💞 红线对象 <span class="arrow-toggle">▼</span></summary>
                    <div class="section-content">
                        ${renderDestinyTargets()}
                    </div>
                </details>

                <details class="section">
                    <summary>🌍 今天发生了啥？<span class="arrow-toggle">▼</span></summary>
                    <div class="section-content">
                        ${renderNews()}
                    </div>
                </details>
            </div>

            <script>
            // Kora注：这是一个小型的、自执行的交互脚本。它的唯一作用是处理UI的折叠/展开动画。
            // 因为所有数据都已由上面的模板字符串渲染完毕，所以这里的脚本无需再次获取数据，非常高效。
            (function() {
                const panel = document.getElementById('kora-status-panel-${new Date().getTime()}');
                if (panel) {
                    panel.querySelectorAll('details > summary').forEach(summary => {
                        summary.addEventListener('click', function(event) {
                            // 使用一个微小的延迟来确保 'open' 属性已经更新
                            setTimeout(() => {
                                const detailsElement = summary.parentElement;
                                const arrow = summary.querySelector('.arrow-toggle');
                                if (arrow) {
                                    arrow.style.transform = detailsElement.open ? 'rotate(90deg)' : '';
                                }
                            }, 0);
                        });
                        // 初始化箭头状态
                         const initialDetails = summary.parentElement;
                         const initialArrow = summary.querySelector('.arrow-toggle');
                         if(initialArrow) {
                            initialArrow.style.transform = initialDetails.open ? 'rotate(90deg)' : '';
                         }
                    });
                }
            })();
            </script>
        </div>
        `;
    }

    // ----------------------------------------------------------------------------------
    // 步骤三：UI更新与替换函数 (updateStatusBlock)
    // ----------------------------------------------------------------------------------
    // 此函数负责在SillyTavern渲染一条新消息时被触发，执行UI的替换逻辑。
    async function updateStatusBlock(message_id) {
        // 1. 获取该楼层的原始消息内容
        const message = (await getChatMessages(message_id))?.[0];
        if (!message || !message.message || !statusblock_regex.test(message.message)) return;

        // 2. [核心步骤] 获取该消息楼层对应的、最权威的stat_data
        const variables = await getVariables({ type: 'message', message_id: message_id });
        if (!variables || !variables.stat_data) {
            console.log(`[Kora UI] Message ${message_id} has no stat_data to render.`);
            return;
        }

        // 3. 调用我们的核心渲染函数，传入数据，生成UI面板的HTML字符串
        const statusHTML = generateStatusBlock(variables);

        // 4. 在前端DOM中找到SillyTavern显示消息的元素
        const $mes_text = retrieveDisplayedMessage(message_id);
        if ($mes_text.length === 0) return;

        // 5. [核心步骤] 将消息元素中的占位符，用我们刚刚生成的UI面板进行替换
        const currentContent = $mes_text.html();
        const updatedContent = currentContent.replace(statusblock_regex, statusHTML);
        $mes_text.html(updatedContent);
    }

    // ----------------------------------------------------------------------------------
    // 步骤四：将脚本挂载到SillyTavern的事件系统 (initializeStatusBlocks)
    // ----------------------------------------------------------------------------------
    // Kora注：这是让脚本“活”起来的关键。我们使用`eventOn` API来监听SillyTavern的内部事件。
    async function initializeStatusBlocks() {
        // 监听“角色消息渲染完成”事件
        eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, updateStatusBlock);
        // 监听“消息被编辑/重绘”事件
        eventOn(tavern_events.MESSAGE_UPDATED, updateStatusBlock);
        // 监听“消息被切换”事件
        eventOn(tavern_events.MESSAGE_SWIPED, updateStatusBlock);

        // 为了确保在刷新页面或加载历史记录时UI也能正确显示，
        // 我们在脚本初始化时，为所有已存在的历史消息也执行一次UI渲染。
        const chatMessages = document.querySelectorAll('#chat .mes[is_user="false"]');
        for (const messageElement of chatMessages) {
            const messageId = Number(messageElement.getAttribute("mesid"));
            if (!isNaN(messageId)) {
                await updateStatusBlock(messageId);
            }
        }
    }

    // ----------------------------------------------------------------------------------
    // 步骤五：启动脚本
    // ----------------------------------------------------------------------------------
    initializeStatusBlocks();

})();

(function () {
    'use strict';

    if (window.dynamicLogSystemInitialized) {
        return;
    }

    // --- 日志系统核心对象 ---
    const logSystem = {
        // 运行状态
        state: {
            allLogs: [],
            filteredLogs: [],
            currentPage: 1,
            itemsPerPage: 10,
            filter: '全部',
            searchTerm: '',
        },
        // API配置
        config: {
            isEnabled: true,
            apiUrl: '',
            apiKey: '',
            model: '',
            metaPrompt: `You are a Log Archiver. Your task is to analyze the last user message and the character's response to identify the single most important event that occurred. Summarize this event into a structured JSON object with the keys "type", "time", "location", and "description".

- "type": Choose one from ["任务", "关系", "战斗", "探索", "系统"].
- "time": Get the current in-game time from the provided variables.
- "location": Get the current in-game location from the provided variables.
- "description": Write a concise, neutral, third-person summary of the key event.

Example Input Dialogue:
User: I'll accept the quest to find the Sunstone.
Assistant: "Excellent," the guild master says, "The Sunstone is said to be in the Shadowfen Crypt. Be careful."

Example Output JSON:
{
  "type": "任务",
  "time": "辉煌纪元489年-丰收之月-3日",
  "location": "冒险者公会",
  "description": "接取了任务“寻找日长石”，目标地点为“影沼地穴”。"
}

Now, analyze the following dialogue and variables. Output only the JSON object and nothing else.`,
        },

        // 从localStorage加载/保存配置
        loadConfig: () => {
            const savedConfig = localStorage.getItem('dynamicLogSystemConfig');
            if (savedConfig) {
                try {
                    Object.assign(logSystem.config, JSON.parse(savedConfig));
                } catch (e) {
                    console.error("动态日志：加载配置失败", e);
                }
            }
        },
        saveConfig: () => {
            localStorage.setItem('dynamicLogSystemConfig', JSON.stringify(logSystem.config));
            toastr.success("日志API配置已保存。");
        },

        // 应用筛选和搜索
        applyFilters: () => {
            let logs = [...logSystem.state.allLogs];
            if (logSystem.state.filter !== '全部') {
                logs = logs.filter(entry => entry && entry.type === logSystem.state.filter);
            }
            if (logSystem.state.searchTerm) {
                const term = logSystem.state.searchTerm.toLowerCase();
                logs = logs.filter(entry => entry && entry.description && (entry.description.toLowerCase().includes(term) || (entry.location && entry.location.toLowerCase().includes(term))));
            }
            logSystem.state.filteredLogs = logs;
            logSystem.state.currentPage = 1;
        },

        // 渲染日志条目和分页
        renderEntries: () => {
            const container = document.getElementById('log-entries-container');
            if (!container) return;

            const startIndex = (logSystem.state.currentPage - 1) * logSystem.state.itemsPerPage;
            const endIndex = startIndex + logSystem.state.itemsPerPage;
            const paginatedLogs = logSystem.state.filteredLogs.slice(startIndex, endIndex);

            if (paginatedLogs.length === 0) {
                container.innerHTML = '<p class="empty-state-text" style="color:#a0a0a0; font-style:italic; text-align:center;">没有符合条件的日志。</p>';
            } else {
                container.innerHTML = paginatedLogs.map(entry => {
                    if (!entry || typeof entry !== 'object') return ''; // 安全检查
                    return `
                    <div class="log-entry" style="margin-bottom:10px; padding-bottom:10px; border-bottom:1px solid rgba(255,255,255,0.1);">
                        <div class="log-entry-header" style="font-size:0.9em; color:#a0a0a0; margin-bottom:5px; display:flex; flex-wrap:wrap; gap:10px;">
                            <span class="log-type" style="background-color:rgba(255,255,255,0.1); padding:2px 6px; border-radius:3px; font-size:0.8em;">${entry.type || '通用'}</span>
                            <span>${entry.time || '未知时间'}</span>
                            <span>@ ${entry.location || '未知地点'}</span>
                        </div>
                        <p style="margin:0; color:#e0e0e0;">${entry.description || '(无描述)'}</p>
                    </div>`;
                }).join('');
            }

            const pageInfo = document.getElementById('log-page-info');
            const totalPages = Math.max(1, Math.ceil(logSystem.state.filteredLogs.length / logSystem.state.itemsPerPage));
            if(pageInfo) {
                pageInfo.textContent = `第 ${logSystem.state.currentPage} / ${totalPages} 页`;
            }
            document.getElementById('log-prev-page').disabled = logSystem.state.currentPage <= 1;
            document.getElementById('log-next-page').disabled = logSystem.state.currentPage >= totalPages;
        },

        // 显示主弹窗
        showPopup: () => {
            // 在打开弹窗前，先从最新的变量中同步一次日志数据
            try {
                const latestVars = TavernHelper.getVariables({ type: 'chat' });
                const journalTuple = latestVars['日志'];
                logSystem.state.allLogs = (Array.isArray(journalTuple) && Array.isArray(journalTuple[0])) ? journalTuple[0] : [];
            } catch (e) {
                console.error("动态日志：同步最新日志数据失败", e);
                logSystem.state.allLogs = [];
            }

            const popupContent = `
                <div class="log-popup-content" style="display:flex; flex-direction:column; gap:15px; color:#e0e0e0;">
                    <div class="log-header" style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
                        <h3 style="margin:0;">冒险日志</h3>
                        <div class="log-filters" style="display:flex; gap:5px; flex-wrap:wrap;">
                            ${['全部', '任务', '关系', '战斗', '探索', '系统'].map(f => `<button data-filter="${f}" class="log-filter-btn ${logSystem.state.filter === f ? 'active' : ''}" style="background-color:rgba(255,255,255,0.1); border:1px solid rgba(255,255,255,0.2); color:#e0e0e0; padding:5px 10px; border-radius:4px; cursor:pointer; transition: background-color 0.2s;">${f}</button>`).join('')}
                        </div>
                        <button id="log-settings-btn" style="background:none; border:none; color:#ccc; font-size:1.2em; cursor:pointer;" title="配置日志API">⚙️</button>
                    </div>
                    <div class="log-search" style="flex-grow:1; min-width:150px;"><input type="text" id="log-search-input" placeholder="搜索关键词..." value="${logSystem.state.searchTerm}" style="width:100%; box-sizing:border-box; background-color:rgba(0,0,0,0.3); border:1px solid rgba(255,255,255,0.2); color:#e0e0e0; padding:8px; border-radius:4px;"></div>
                    <div id="log-entries-container" class="log-entries" style="min-height:300px; max-height:40vh; overflow-y:auto; padding-right:10px;"></div>
                    <div class="log-pagination" style="display:flex; justify-content:center; align-items:center; gap:15px; margin-top:10px;">
                        <button id="log-prev-page" style="background:none; border:1px solid #888; color:#888; cursor:pointer; border-radius:4px; padding:5px 10px;">上一页</button>
                        <span id="log-page-info"></span>
                        <button id="log-next-page" style="background:none; border:1px solid #888; color:#888; cursor:pointer; border-radius:4px; padding:5px 10px;">下一页</button>
                    </div>
                </div>
            `;

            new SillyTavern.Popup(popupContent, { wider: true, okButton: '关闭' });

            setTimeout(() => {
                const filterButtons = document.querySelectorAll('.log-filter-btn');
                filterButtons.forEach(btn => {
                    btn.addEventListener('click', (e) => {
                        logSystem.state.filter = e.target.dataset.filter;
                        filterButtons.forEach(b => b.classList.remove('active'));
                        e.target.classList.add('active');
                        // 修正激活按钮的样式
                        e.target.style.backgroundColor = '#6a4acd';
                        e.target.style.borderColor = '#6a4acd';
                        Array.from(filterButtons).filter(b => b !== e.target).forEach(b => {
                            b.style.backgroundColor = 'rgba(255,255,255,0.1)';
                            b.style.borderColor = 'rgba(255,255,255,0.2)';
                        });
                        logSystem.applyFilters();
                        logSystem.renderEntries();
                    });
                });
                 // 初始化时，确保激活按钮有正确样式
                document.querySelector(`.log-filter-btn[data-filter="${logSystem.state.filter}"]`)?.classList.add('active');
                const activeButton = document.querySelector('.log-filter-btn.active');
                if(activeButton) {
                    activeButton.style.backgroundColor = '#6a4acd';
                    activeButton.style.borderColor = '#6a4acd';
                }


                document.getElementById('log-search-input').addEventListener('input', (e) => {
                    logSystem.state.searchTerm = e.target.value;
                    logSystem.applyFilters();
                    logSystem.renderEntries();
                });

                document.getElementById('log-prev-page').addEventListener('click', () => {
                    if (logSystem.state.currentPage > 1) {
                        logSystem.state.currentPage--;
                        logSystem.renderEntries();
                    }
                });
                document.getElementById('log-next-page').addEventListener('click', () => {
                    const totalPages = Math.ceil(logSystem.state.filteredLogs.length / logSystem.state.itemsPerPage);
                    if (logSystem.state.currentPage < totalPages) {
                        logSystem.state.currentPage++;
                        logSystem.renderEntries();
                    }
                });
                document.getElementById('log-settings-btn').addEventListener('click', logSystem.showSettingsPopup);

                logSystem.applyFilters();
                logSystem.renderEntries();
            }, 100);
        },

        // 显示API配置弹窗
        showSettingsPopup: () => {
            const settingsContent = `
                <div>
                    <h4>动态日志 API 配置</h4>
                    <p style="font-size:0.9em; color:#ccc;">为后台日志生成指定独立的API。保存后将在下次自动更新时生效。</p>
                    <label class="log-settings-label" style="display:block; margin-top:10px; margin-bottom:5px;"><input type="checkbox" id="log-api-enabled" ${logSystem.config.isEnabled ? 'checked' : ''}> 启用自动日志</label>
                    <hr>
                    <label class="log-settings-label" style="display:block; margin-top:10px; margin-bottom:5px;" for="log-api-url">API URL:</label>
                    <input type="text" id="log-api-url" class="log-settings-input" style="width:100%; box-sizing:border-box; background-color:rgba(0,0,0,0.5); border:1px solid #888; color:#e0e0e0; padding:8px; border-radius:4px;" value="${logSystem.config.apiUrl}">
                    <label class="log-settings-label" style="display:block; margin-top:10px; margin-bottom:5px;" for="log-api-key">API Key:</label>
                    <input type="password" id="log-api-key" class="log-settings-input" style="width:100%; box-sizing:border-box; background-color:rgba(0,0,0,0.5); border:1px solid #888; color:#e0e0e0; padding:8px; border-radius:4px;" value="${logSystem.config.apiKey}">
                    <label class="log-settings-label" style="display:block; margin-top:10px; margin-bottom:5px;" for="log-api-model">模型名称:</label>
                    <input type="text" id="log-api-model" class="log-settings-input" style="width:100%; box-sizing:border-box; background-color:rgba(0,0,0,0.5); border:1px solid #888; color:#e0e0e0; padding:8px; border-radius:4px;" value="${logSystem.config.model}">
                    <label class="log-settings-label" style="display:block; margin-top:10px; margin-bottom:5px;" for="log-meta-prompt">日志生成指令 (Meta-Prompt):</label>
                    <textarea id="log-meta-prompt" class="log-settings-input" style="width:100%; box-sizing:border-box; background-color:rgba(0,0,0,0.5); border:1px solid #888; color:#e0e0e0; padding:8px; border-radius:4px;" rows="8">${logSystem.config.metaPrompt}</textarea>
                </div>
            `;
            new SillyTavern.Popup(settingsContent, { 
                okButton: '保存', 
                cancelButton: '取消',
                onOk: () => {
                    logSystem.config.isEnabled = document.getElementById('log-api-enabled').checked;
                    logSystem.config.apiUrl = document.getElementById('log-api-url').value;
                    logSystem.config.apiKey = document.getElementById('log-api-key').value;
                    logSystem.config.model = document.getElementById('log-api-model').value;
                    logSystem.config.metaPrompt = document.getElementById('log-meta-prompt').value;
                    logSystem.saveConfig();
                }
            });
        }
    };

    // --- 后台自动更新逻辑 ---
    async function handleNewMessage() {
        if (!logSystem.config.isEnabled || !logSystem.config.apiUrl || !logSystem.config.apiKey || !logSystem.config.model) {
            console.log('动态日志：自动更新已禁用或未配置API，跳过生成。');
            return;
        }

        try {
            const chatHistory = await TavernHelper.getChatMessages(-2, { include_swipes: false });
            if (chatHistory.length < 2) return;

            const latestVars = TavernHelper.getVariables({ type: 'chat' });
            const worldTime = (latestVars['世界'] && latestVars['世界'][0]) ? latestVars['世界'][0]['时间'][0] : '未知时间';
            const worldLocation = (latestVars['世界'] && latestVars['世界'][0]) ? latestVars['世界'][0]['地点'][0] : '未知地点';

            const lastTwoTurns = `User: ${chatHistory[0].message}\nAssistant: ${chatHistory[1].message}`;
            const metaPrompt = `${logSystem.config.metaPrompt}\n\nCurrent In-Game Variables:\n- Time: ${worldTime}\n- Location: ${worldLocation}\n\nLast Dialogue Turn:\n${lastTwoTurns}`;

            console.log('动态日志：触发后台生成...');
            const generatedJson = await TavernHelper.generate({
                user_input: metaPrompt,
                max_chat_history: 0,
                custom_api: {
                    apiurl: logSystem.config.apiUrl,
                    key: logSystem.config.apiKey,
                    model: logSystem.config.model
                }
            });

            let newLogEntry;
            try {
                 const jsonMatch = generatedJson.trim().match(/\{[\s\S]*\}/);
                 if (!jsonMatch) throw new Error("API did not return a JSON object.");
                 newLogEntry = JSON.parse(jsonMatch[0]);
            } catch(e) {
                console.error('动态日志：API返回的不是有效的JSON，内容:', generatedJson, e);
                return;
            }
            if (typeof newLogEntry !== 'object' || !newLogEntry.description) {
                console.error('动态日志：解析后的JSON格式不正确或缺少描述。', newLogEntry);
                return;
            }

            await TavernHelper.updateVariablesWith(variables => {
                const currentLogs = (variables['日志'] && Array.isArray(variables['日志'][0])) ? variables['日志'][0] : [];
                currentLogs.unshift(newLogEntry);
                _.set(variables, '日志[0]', currentLogs);
                return variables;
            }, { type: 'chat' });

            console.log('动态日志：成功自动添加一条新日志。');

        } catch (error) {
            console.error('动态日志：自动生成日志失败:', error);
        }
    }

    // --- 脚本初始化与事件绑定 ---
    function initialize() {
        console.log("动态日志脚本 v1.1 初始化...");
        logSystem.loadConfig();

        // 将logSystem暴露到顶层窗口，以便UI文件直接调用
        if (window.top) {
            window.top.dynamicLogSystem = logSystem;
        } else {
            window.dynamicLogSystem = logSystem;
        }

        // 监听AI的新回复，触发自动日志
        if (TavernHelper && TavernHelper.eventOn) {
            TavernHelper.eventOn('tavern_events.MESSAGE_RECEIVED', handleNewMessage);
        }

        console.log("动态日志脚本 v1.1 加载完毕。");
    }

    // 等待TavernHelper API加载完毕后再执行
    if (typeof TavernHelper !== 'undefined' && TavernHelper.getTavernHelperVersion) {
        initialize();
    } else {
        document.addEventListener('TavernHelperLoaded', initialize, { once: true });
    }

    window.dynamicLogSystemInitialized = true;

})();

