<body>
    <div id="status-container-wrapper"></div>
    <script>
    // [V4.4 - 移除战斗]
    let currentInventoryFilter = '全部', currentSkillsFilter = '全部';
    let currentProtagonistTab = 'core';
    window.last_stat_data = {};

    // --- 核心函数 (SafeGetValue 修正版) ---
    const SafeGetValue = (obj, path, defaultValue) => {
        try {
            const keys = path.split('.'); let current = obj;
            for (let i = 0; i < keys.length; i++) {
                const key = keys[i]; if (current === null || typeof current !== 'object') { return defaultValue; }
                const match = key.match(/^(.+?)\[(\d+)\]$/); // V2.6 Correct Regex Literal
                if (match) {
                    const arrayKey = match[1]; const index = parseInt(match[2], 10);
                    if (current.hasOwnProperty(arrayKey) && Array.isArray(current[arrayKey]) && index >= 0 && index < current[arrayKey].length) { current = current[arrayKey][index]; }
                    else { return defaultValue; }
                } else if (current.hasOwnProperty(key)) { current = current[key]; }
                else { return defaultValue; }
            } return current === undefined ? defaultValue : current;
        } catch (error) { console.error(`SafeGetValue CRITICAL ERROR for path \"${path}\" in obj:`, obj, 'Error:', error); return defaultValue; }
    };
    const setContent = (id, content) => { const el = document.getElementById(id); if (el) el.innerHTML = content; };
    const setToggle = (id, visible) => { const el = document.getElementById(id); if (el) el.classList.toggle('hidden', !visible); };
    const updateProgressBar = (barId, current, max, color, shadowColor = null) => { const bar = document.getElementById(barId); if (bar) { const percentage = max > 0 ? (current / max) * 100 : 0; bar.style.width = `${Math.max(0, Math.min(100, percentage))}%`; } };
    function sendCommand(command) { if (typeof triggerSlash === 'function') { triggerSlash(command); } else { console.error('triggerSlash function not found. Command:', command); alert(`模拟发送指令 (请在SillyTavern中测试):\n${command}`); } }
    // --- End Core Functions ---

    // --- [已移除] getParticipantData, renderActionQueue, formatQueuedActions ---

    // --- [修改 V4.4] 简化的 renderUI ---
    function renderUI(data) {
        // console.log("--- renderUI called (Non-Combat) ---");
        window.last_stat_data = data;
        const container = document.getElementById('status-container-wrapper');
        if (!container) { console.error("Missing #status-container-wrapper"); return; }
        if (!container.innerHTML) container.innerHTML = `<div id="status-container" class="status-container"></div>`;

        // 始终显示 Status UI
        setToggle('status-container-wrapper', true);

        // 尝试隐藏战斗 UI (以防万一)
        const combatContainer = document.getElementById('combat-display-wrapper');
        if (combatContainer) setToggle('combat-display-wrapper', false);

        renderStatusUI(data);
    }

    // --- [已移除] renderCombatUI, renderProtagonistStats, renderAlliesDisplay ---

    // --- Status UI Functions (与 V3.9 相同) ---
    function renderStatusUI(data) {
        const container = document.getElementById('status-container');
        if (!container) return;
        const sectionIcons = { '主角': 'fa-book-skull', '探索附近': 'fa-compass', '人脉关系': 'fa-users-viewfinder', '命运系统': 'fa-hands-holding-circle', '当前任务': 'fa-scroll', '财产': 'fa-gem', '今日新闻': 'fa-newspaper', '世界图鉴': 'fa-atlas' };
        const sectionOrder = ['主角', '探索附近', '人脉关系', '命运系统', '当前任务', '财产', '今日新闻', '世界图鉴'];
        let sectionsHtml = sectionOrder.map(title => {
            const iconClass = sectionIcons[title] || 'fa-question-circle';
            const sectionId = { '主角': 'protagonist-section', '探索附近': 'map-section', '人脉关系': 'contacts-section', '命运系统': 'destiny-section', '当前任务': 'tasks-section', '财产': 'assets-section', '今日新闻': 'news-section', '世界图鉴': 'codex-section' }[title];
            const contentPadding = (title === '主角') ? 'padding: 5px 15px 15px 15px;' : '';
            return `<details class="section"> <summary><i class="fa-solid ${iconClass} fa-fw summary-icon"></i>${title}<span class="arrow-toggle">&gt;</span></summary> <div class="section-content" id="${sectionId}" style="${contentPadding}"></div> </details>`;
        }).join('');
        container.innerHTML = `<div class="world-info-box" id="world-info-box"></div> ${sectionsHtml}`;

        const worldData = SafeGetValue(data, '世界', {});
        populateWorldInfo(worldData);
        populateProtagonist(SafeGetValue(data, '主角', {}));
        populateMap(worldData);
        populateDestinyAndContacts(data);
        const tasksContainer = SafeGetValue(data, '任务列表', []);
        const tasksData = Array.isArray(tasksContainer) && tasksContainer.length > 0 ? tasksContainer[0] : {};
        populateQuests(tasksData);
        populateAssets(SafeGetValue(data, '财产', {}));
        populateNews(SafeGetValue(data, '今日新闻', {}));
        populateCodex(SafeGetValue(data, '世界图鉴', []));
    }

    function populateWorldInfo(worldData) { setContent('world-info-box', ` <div><p><span class="property-name"><i class="fa-solid fa-clock icon"></i> 时间:</span> <span class="value-main">${SafeGetValue(worldData, '时间[0]', '未知')}</span></p></div> <div><p><span class="property-name"><i class="fa-solid fa-map-location-dot icon"></i> 地点:</span> <span class="value-main">${SafeGetValue(worldData, '地点[0]', '未知')}</span></p></div> <div><p><span class="property-name"><i class="fa-solid fa-cloud-sun icon"></i> 天气:</span> <span class="value-main">${SafeGetValue(worldData, '天气[0]', '未知')}</span></p></div> <div><p><span class="property-name"><i class="fa-solid fa-person-rays icon"></i> 声望:</span> <span class="value-main">${SafeGetValue(worldData, '当前声望[0]', 0)}</span></p></div>`); }

    function populateProtagonist(data) {
        const resources = SafeGetValue(data, '资源', {}); const equipmentContainer = SafeGetValue(data, '装备', []); const equipment = Array.isArray(equipmentContainer) && equipmentContainer.length > 0 ? equipmentContainer[0] : {}; const statusEffectsContainer = SafeGetValue(data, '状态效果', []); const statusEffects = Array.isArray(statusEffectsContainer) && statusEffectsContainer.length > 0 ? statusEffectsContainer[0] : {}; const skillsContainer = SafeGetValue(data, '技能', []); const skills = Array.isArray(skillsContainer) && skillsContainer.length > 0 ? skillsContainer[0] : {};
        const hp = SafeGetValue(resources, '生命值[0]', 0); const maxHp = SafeGetValue(resources, '生命值上限[0]', 1); const mp = SafeGetValue(resources, '法力值[0]', 0); const maxMp = SafeGetValue(resources, '法力值上限[0]', 1); const sp = SafeGetValue(resources, '体力值[0]', 0); const maxSp = SafeGetValue(resources, '体力值上限[0]', 1);
        const effectKeys = typeof statusEffects === 'object' && statusEffects !== null ? Object.keys(statusEffects).filter(k => k !== '$meta') : []; const skillKeys = typeof skills === 'object' && skills !== null ? Object.keys(skills).filter(k => k !== '$meta') : [];
        const emptyIcon = `<i class="fa-solid fa-scroll fa-xs" style="opacity: 0.6; margin-right: 5px;"></i>`;
        const resourcesHtml = `<div class="detail-grid" style="gap: 6px;"> <div class="resource-grid-item" style="border: none; padding-bottom: 0;"> <div class="resource-row"> <span class="icon" style="color:var(--hp-color);"><i class="fa-solid fa-heart"></i></span> <div class="progress-bar-container"><div id="main-hp-bar" class="progress-bar-value"></div></div> <span class="value-main">${hp} / ${maxHp}</span> </div> </div> <div class="resource-grid-item" style="border: none; padding-bottom: 0;"> <div class="resource-row"> <span class="icon" style="color:var(--mp-color);"><i class="fa-solid fa-wand-sparkles"></i></span> <div class="progress-bar-container"><div id="main-mp-bar" class="progress-bar-value"></div></div> <span class="value-main">${mp} / ${maxMp}</span> </div> </div> <div class="resource-grid-item" style="border: none; padding-bottom: 0;"> <div class="resource-row"> <span class="icon" style="color:var(--stamina-color);"><i class="fa-solid fa-person-running"></i></span> <div class="progress-bar-container"><div id="main-sp-bar" class="progress-bar-value"></div></div> <span class="value-main">${sp} / ${maxSp}</span> </div> </div> </div>`;
        const staticHtml = `<hr> <div class="detail-grid"> <div class="detail-grid-item"><span class="icon"><i class="fa-solid fa-id-card"></i></span><span class="property-name">姓名</span><span class="value-main">${SafeGetValue(data, '姓名[0]', '未设定')}</span></div> <div class="detail-grid-item"><span class="icon"><i class="fa-solid fa-shield-halved"></i></span><span class="property-name">身份</span><span class="value-main">${SafeGetValue(data, '身份[0]', '无')}</span></div> <div class="detail-grid-item"><span class="icon"><i class="fa-solid fa-khanda"></i></span><span class="property-name">力量层次</span><span class="value-main">${SafeGetValue(data, '力量层次[0]', '凡人')}</span></div> </div>`;
        const equipmentHtml = `<div class="detail-grid"> <div class="detail-grid-item"><span class="icon"><i class="fa-solid fa-gavel"></i></span><span class="property-name">武器</span><span class="value-main">${SafeGetValue(equipment, '武器[0]', '(无)')}</span></div> <div class="detail-grid-item"><span class="icon"><i class="fa-solid fa-shirt"></i></span><span class="property-name">盔甲</span><span class="value-main">${SafeGetValue(equipment, '盔甲[0]', '(无)')}</span></div> <div class="detail-grid-item"><span class="icon"><i class="fa-solid fa-ring"></i></span><span class="property-name">饰品</span><span class="value-main">${SafeGetValue(equipment, '饰品[0]', '(无)')}</span></div> </div>`;
