        h2.section-title{font-family:var(--font-title);color:var(--title-color);border-bottom:1px solid var(--border-color-light);padding-bottom:8px;margin-top:30px;margin-bottom:20px;font-size:1.4em;letter-spacing:1px}
        .main-title{font-family:var(--font-title);font-weight:700;color:var(--title-color);text-align:center;font-size:1.8em;letter-spacing:2px;margin:0 0 25px 0}
        .reincarnation-points{font-family:var(--font-title);font-weight:700;color:var(--points-color);font-size:1.1em;padding:10px;background-color:var(--button-bg-color);border:1px solid var(--border-color-strong);text-align:center;margin-bottom:15px;width:100%;box-sizing:border-box;position:sticky;top:0;z-index:100}
        .input-group{margin-bottom:20px}
        label{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-weight:500;color:var(--title-color);font-size:1.05em}
        input[type=text],input[type=number],select,textarea{width:100%;padding:10px 12px;border:1px solid var(--border-color-light);background-color:var(--input-bg-color);color:var(--text-color);font-family:var(--font-body);font-size:1em;box-sizing:border-box;transition:border-color .2s,box-shadow .2s;resize:vertical}
        input:focus,select:focus,textarea:focus{outline:none;border-color:var(--border-color-strong);box-shadow:0 0 5px rgba(120,90,78,.4)}
        input[type=range]{width:100%;-webkit-appearance:none;appearance:none;height:8px;background:var(--border-color-light);outline:0;cursor:pointer}
        input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:20px;height:20px;background:var(--title-color);cursor:pointer;border:2px solid var(--border-color-strong)}
        .attributes-container{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}
        .attribute-control{display:flex;align-items:center;justify-content:space-between;background-color:var(--input-bg-color);padding:5px 10px;border:1px solid var(--border-color-light)}
        .attribute-control .stat-name{font-weight:500}
        .attribute-control .stat-value{font-weight:700;color:var(--title-color)}
        .attribute-control .ap-buttons{display:flex;align-items:center}
        .attribute-control .ap-btn{background-color:var(--button-bg-color);border:1px solid var(--border-color-strong);color:var(--text-color);font-weight:700;cursor:pointer;width:25px;height:25px;line-height:22px;text-align:center;transition:background-color .2s}
        .attribute-control .ap-btn:disabled{background-color:#e0e0e0;cursor:not-allowed}
        .attribute-control .ap-input{width:40px;text-align:center;border:none;background:0 0;font-weight:500;color:var(--points-color);-moz-appearance:textfield}
        .custom-input,.conditional-display-group{display:none;margin-top:10px}
        .custom-input.show,.conditional-display-group.show{display:block}
        .narrative-vignette{background-color:rgba(0,0,0,0.05);border-left:3px solid var(--border-color-strong);padding:10px 15px;margin-top:10px;font-size:.9em;font-style:italic}
        .skill-option{display:flex;align-items:flex-start;cursor:pointer;padding:10px;border:1px solid var(--border-color-light);background-color:var(--input-bg-color);transition:background-color .2s,border-color .2s}
        .skill-option:hover{background-color:rgba(220,210,190,.6);border-color:var(--border-color-strong)}
        .skill-option-content{display:flex;flex-direction:column;flex-grow:1}
        .skill-main-info{font-weight:500;color:var(--title-color)}
        .skill-description{margin-top:6px;font-size:.85em;color:var(--text-color)}
        .skill-option input[type=checkbox],.skill-option input[type=radio]{margin-right:12px;margin-top:4px;-webkit-appearance:none;appearance:none;width:16px;height:16px;border:1px solid var(--border-color-strong);position:relative;cursor:pointer;flex-shrink:0}
        .skill-option input:checked{background-color:var(--title-color)}
        .skill-option input:checked::after{content:'✔';color:#fff;font-size:11px;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%)}
        .selection-btn,.submit-button,.modal-confirm-btn{padding:12px;font-family:var(--font-body);font-weight:700;color:var(--title-color);background-color:var(--button-bg-color);border:1px solid var(--border-color-strong);cursor:pointer;transition:all .2s ease;width:100%;font-size:1.1em}
        .selection-btn:hover,.submit-button:hover,.modal-confirm-btn:hover{background-color:#c6b8a5}
        .selection-control{display:flex;flex-direction:column;gap:8px}
        .selection-summary{font-size:.85em;color:var(--text-color);padding-left:5px}
        .rarity-common{color:#6c757d}.rarity-uncommon{color:#4caf50}.rarity-rare{color:#2196f3}.rarity-epic{color:#9c27b0}.rarity-legendary{color:#ffc107}.rarity-mythic{color:#f44336}
        .skill-main-info .rarity-common,.skill-main-info .rarity-uncommon,.skill-main-info .rarity-rare,.skill-main-info .rarity-epic,.skill-main-info .rarity-legendary,.skill-main-info .rarity-mythic{font-weight:700}
        .modal{display:none;position:fixed;z-index:1000;left:0;top:0;width:100%;height:100%;background-color:rgba(0,0,0,.6)}
        .modal-content{background-color:var(--bg-color);margin:5% auto;padding:25px;border:2px solid var(--border-color-strong);width:90%;max-width:600px}
        .modal-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}
        .modal-title{font-family:var(--font-title);font-size:1.5em;color:var(--title-color);margin:0}
        .close-btn{font-size:28px;font-weight:700;cursor:pointer}
        .modal-options-list{display:flex;flex-direction:column;gap:10px;max-height:55vh;overflow-y:auto;padding-right:10px}
        .modal-footer{margin-top:20px;text-align:right}
        small{color:var(--text-color);opacity:.8}
        .world-state-group .slider-label{display:flex;justify-content:space-between;font-size:.9em}
        .modal-custom-section{margin-top:15px;border-top:1px solid var(--border-color-light);padding-top:15px}
    </style>
</head>
<body>
    <div class="creator-scroll">
        <div class="main-title">异世界之旅：命运之织 V5.0</div>
        <div class="reincarnation-points">可用转生点: <span id="reincarnationPointsDisplay">0</span></div>

        <h2 class="section-title">I. 前世追忆</h2>
        <div class="input-group"><label for="pastLifeInput">选择你的前世以决定起点</label><select id="pastLifeInput"></select><small>前世遗泽: <span id="legacyDescription"></span></small></div>

        <h2 class="section-title">II. 现世之塑</h2>
        <div class="input-group"><label for="nameInput">🖋️ 姓名</label><input type="text" id="nameInput" placeholder="一个将要响彻大陆的名字..." /></div>
        <div class="input-group"><label for="genderInput">🌗 性别</label><select id="genderInput"><option value="" disabled selected>选择你的存在形态</option><option value="男">男</option><option value="女">女</option><option value="custom">自定义</option></select><input type="text" id="customGenderInput" class="custom-input" placeholder="超越凡俗的想象..." /></div>
        <div class="input-group"><label for="ageInput">⏳ 年龄</label><input type="number" id="ageInput" placeholder="你的故事从何处开始" min="0" /></div>
        <div class="input-group"><label for="raceInput">🩸 种族</label><select id="raceInput"></select><input type="text" id="customRaceInput" class="custom-input" placeholder="一种未被记载于世界书的血脉..." /></div>
        <div class="input-group"><label for="identityInput">👑 身份</label><select id="identityInput"></select><input type="text" id="customIdentityInput" class="custom-input" placeholder="一段不为人知的过往..." /></div>
        <div class="input-group"><label for="startLocationInput">🗺️ 起始地点</label><select id="startLocationInput"></select></div>
        <div id="originVignette" class="narrative-vignette" style="display:none;"></div>

        <h2 class="section-title">III. 天赋与缺陷</h2>
        <div class="input-group" id="attributes-group"><label>🎲 初始属性 <small>(基础4, 可用点: <span id="apDisplay">5</span>)</small></label><div class="attributes-container"></div></div>
        <div class="input-group"><label>💫 初始技能与天赋</label><div class="selection-control"><button class="selection-btn" data-category="skills">选择技能/天赋</button><div class="selection-summary" id="skillsSummary">已选0项，消耗0点</div></div></div>
        <div class="input-group"><label>🥀 负面特质</label><div class="selection-control"><button class="selection-btn" data-category="negativeTraits">选择缺陷以换取点数</button><div class="selection-summary" id="negativeTraitsSummary">已选0项，获得0点</div></div></div>

        <h2 class="section-title">IV. 初始羁绊与行囊</h2>
        <div class="input-group"><label>❤️ 初始伙伴</label><div class="selection-control"><button class="selection-btn" data-category="redThreads">选择初始伙伴 (限定一位)</button><div class="selection-summary" id="redThreadsSummary">未选择</div></div></div>
        <div class="input-group conditional-display-group" id="relationshipGroup"><label for="relationshipInput">设定初始关系</label><select id="relationshipInput"></select></div>
        <div id="relationshipVignette" class="narrative-vignette" style="display:none;"></div>
        <div class="input-group"><label>⚔️ 初始装备</label><div class="selection-control"><button class="selection-btn" data-category="equipments">选择装备</button><div class="selection-summary" id="equipmentsSummary">已选0件，消耗0点</div></div></div>
        <div class="input-group"><label>🎒 初始物品</label><div class="selection-control"><button class="selection-btn" data-category="items">选择物品</button><div class="selection-summary" id="itemsSummary">已选0件，消耗0点</div></div></div>

        <h2 class="section-title">V. 世界的序幕</h2>
        <div class="input-group"><label>🧭 初始背景</label><div class="selection-control"><button class="selection-btn" data-category="backgrounds">选择背景剧本...</button><div class="selection-summary" id="backgroundsSummary">未选择</div></div></div>
        <div id="backgroundStoryGroup" class="input-group conditional-display-group"><label>📜 你的背景故事</label><textarea id="backgroundStory" rows="4" placeholder="你选择了自定义背景，请在此处填写你的故事..."></textarea></div>
        <div class="input-group world-state-group"><label>调整世界初始状态 <span class="reincarnation-points-inline">点数调整: <span id="worldStateCost">0</span></span></label>
            <div class="slider-label"><span>帝国衰微</span><span id="imperialStateLabel">秩序井然</span><span>帝国鼎盛</span></div><input type="range" id="imperialState" min="-20" max="20" value="0" step="20">
            <div class="slider-label"><span>深渊沉睡</span><span id="abyssalStateLabel">暗流涌动</span><span>深渊入侵</span></div><input type="range" id="abyssalState" min="-15" max="15" value="0" step="15">
        </div>

        <h2 class="section-title">VI. 系统设定</h2>
        <div class="input-group"><label for="lilithModeInput">AI助手“莉莉丝”模式</label><select id="lilithModeInput"></select></div>
        <div class="input-group"><label>💖 最终命运点数</label><div id="destinyPointsFinal" style="font-weight:bold; color: var(--points-color);">0</div><small>(剩余转生点将自动转化为命运点数，1:10)</small></div>

        <button id="sendButton" class="submit-button">织造命运，踏上旅程</button>
    </div>

