/**
 * @name '机遇驱动'的红线缔结助手
 * @description 当非红线角色好感度达到阈值时，自动出现缔结按钮，一键完成绑定。
 * @version 2.0
 * @author Gemini
 */

(function () {
    if (typeof SillyTavern === 'undefined' || typeof Mvu === 'undefined' || typeof toastr === 'undefined' || typeof _ === 'undefined' || typeof getScriptButtons === 'undefined' || typeof replaceScriptButtons === 'undefined') {
        console.error("此脚本依赖 SillyTavern, Mvu, toastr, lodash, และ get/replaceScriptButtons API。");
        return;
    }

    const BIND_THRESHOLD = 500; // 好感度阈值，可自定义
    let activeOpportunities = new Set(); // 存储当前已生成的缔结按钮的角色key

    // 核心函数：检查并更新缔结机会按钮
    async function checkAndDisplayBindOpportunities() {
        try {
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            if (!mvuData || !mvuData.stat_data) return;

            const contacts = _.get(mvuData, 'stat_data.人脉关系[0]', {});
            const redLineChars = _.get(mvuData, 'stat_data.命运系统.红线对象[0]', {});
            const redLineKeys = new Set(Object.keys(redLineChars));

            const currentOpportunities = new Set();

            // 1. 扫描所有“人脉”，寻找新的机会
            for (const key in contacts) {
                const contact = contacts[key];
                const favor = _.get(contact, '好感度[0]', 0);

                if (favor >= BIND_THRESHOLD && !redLineKeys.has(key)) {
                    currentOpportunities.add(key);
                }
            }

            // 2. 如果机会列表没有变化，则不执行任何UI操作
            if (_.isEqual(activeOpportunities, currentOpportunities)) {
                return;
            }

            // 3. 更新按钮
            let currentButtons = getScriptButtons().filter(btn => !btn.name.startsWith('[❤️ 缔结红线:'));

            currentOpportunities.forEach(key => {
                const characterName = _.get(contacts[key], '姓名[0]');
                if (characterName) {
                    const buttonName = `[❤️ 缔结红线: ${characterName}]`;
                    currentButtons.push({ name: buttonName, visible: true });

                    // 为新出现的按钮动态绑定一次性点击事件
                    if (!activeOpportunities.has(key)) {
                        eventOnce(getButtonEvent(buttonName), () => handleBindExecution(key, characterName));
                    }
                }
            });

            replaceScriptButtons(currentButtons);
            activeOpportunities = currentOpportunities;

        } catch (error) {
            console.error("【红线缔结助手】检查时出错:", error);
        }
    }

    // 执行绑定的函数
    async function handleBindExecution(characterKey, characterName) {
        try {
            toastr.info(`正在将 ${characterName} 缔结为红线对象...`);
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            const characterData = _.get(mvuData, `stat_data.人脉关系[0].${characterKey}`);

            if (!characterData) {
                toastr.error(`操作失败：无法再次找到 ${characterName} 的数据。`);
                return;
            }

            const newRedLineCharacter = _.cloneDeep(characterData);
            _.set(newRedLineCharacter, '记忆回廊', [{ "$meta": { "extensible": true } }]);
            _.set(newRedLineCharacter, '日程表', ["", ""]);

            const assignCommand = `_.assign('命运系统.红线对象[0]', '${characterKey}', ${JSON.stringify(newRedLineCharacter)});`;
            const removeCommand = `_.remove('人脉关系[0]', '${characterKey}');`;

            const newData = await Mvu.parseMessage(`${assignCommand}\n${removeCommand}`, mvuData);

            if (newData) {
                await Mvu.replaceMvuData(newData, { type: 'message', message_id: 'latest' });
                await createChatMessages([{ role: 'system', message: `【系统：你与 ${characterName} 的命运被红线紧密地连接在了一起。】`, is_hidden: true }]);
                toastr.success(`成功将 ${characterName} 缔结为红线对象！`);
            }
        } catch (error) {
            console.error("【红线缔结脚本】执行绑定时出错:", error);
            toastr.error(`缔结 ${characterName} 时发生内部错误。`);
        }
    }

    // 启动监听
    waitGlobalInitialized('Mvu').then(() => {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, checkAndDisplayBindOpportunities);
        console.log("【'机遇驱动'的红线缔结助手】已启动并监听变量更新。");
    });
})();

/**
 * @name AI 变量更新监视与校验脚本
 * @description 自动监听AI的回复，解析其中的变量更新命令，并在执行前进行二次检查，对潜在的路径错误或不规范操作发出警告。
 * @version 1.1
 * @author Gemini
 */

(function () {
    // 确保 lodash 和 toastr 已加载
    if (typeof _ === 'undefined' || typeof toastr === 'undefined') {
        console.error("此脚本需要 lodash 和 toastr 库。");
        return;
    }

    console.log("【AI变量更新监视脚本】已启动。");

    /**
     * 核心校验函数
     * @param {object} lastMessage - 最新的一条聊天消息对象。
     */
    async function validateVariableUpdates(lastMessage) {
        // 仅在AI回复时触发
        if (lastMessage.is_user || !lastMessage.message) {
            return;
        }

        const aiResponseText = lastMessage.message;
        // 使用正则表达式提取所有 _.(set|add|assign|remove) 格式的命令
        const commandRegex = /_\.(set|add|assign|remove)\(([\s\S]*?)\);/g;
        const commands = [...aiResponseText.matchAll(commandRegex)];

        if (commands.length === 0) {
            // AI回复中没有更新命令，无需检查
            return;
        }

        // 获取当前消息楼层关联的变量数据作为校验基准
        // 这是AI看到并据此作出判断的状态
        const mvuData = Mvu.getMvuData({ type: 'message', message_id: lastMessage.message_id });
        const stat_data = mvuData?.stat_data;

        if (!stat_data) {
            toastr.warning("未能获取到当前楼层的 stat_data，无法进行变量更新校验。", "校验脚本警告");
            return;
        }

        const errors = [];

        for (const command of commands) {
            const [, commandType, argsString] = command;

            // 尝试解析参数，这是一个简化版，主要关注第一个参数（路径）
            // 这个解析器假设路径是第一个参数，并且是用单引号或双引号包裹的字符串
            const args = argsString.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/).map(arg => arg.trim());
            const pathString = args[0];
            const path = pathString.substring(1, pathString.length - 1); // 移除首尾的引号

            // 获取父级路径用于存在性检查
            const pathParts = path.replace(/\[(\d+)\]/g, '.$1').split('.');
            const finalKey = pathParts.pop();
            const parentPath = pathParts.join('.');

            switch (commandType) {
                case 'set':
                case 'add':
                    // 对于 set 和 add，父路径必须存在
                    if (parentPath && !_.has(stat_data, parentPath)) {
                        errors.push(`<b>[路径不存在]</b> 命令 <code>_.${commandType}('${path}', ...)</code> 的父路径 <code>'${parentPath}'</code> 不存在。`);
                    }
                    // 特殊检查：如果路径不以 '[0]' 结尾，但目标是个数组，这可能是一个错误的赋值
                    else if (!path.endsWith('[0]') && Array.isArray(_.get(stat_data, path))) {
                         errors.push(`<b>[潜在错误]</b> 命令 <code>_.${commandType}('${path}', ...)</code> 尝试修改一个数组本身，而不是它的值。是否应使用 <code>'${path}[0]'</code>？`);
                    }
                    break;
                case 'assign':
                    // 对于 assign，目标路径（即父路径）必须存在
                    if (!_.has(stat_data, path)) {
                        errors.push(`<b>[目标不存在]</b> 命令 <code>_.assign('${path}', ...)</code> 的目标对象 <code>'${path}'</code> 不存在。`);
                    }
                    break;
                case 'remove':
                    // 对于 remove，父路径必须存在才能移除其中的属性
                    if (parentPath && !_.has(stat_data, parentPath)) {
                         errors.push(`<b>[路径不存在]</b> 命令 <code>_.remove('${path}', ...)</code> 的父路径 <code>'${parentPath}'</code> 不存在。`);
                    }
                    break;
            }
        }

        // 如果收集到错误，则通过 tostr 进行提示
        if (errors.length > 0) {
            const errorMessage = `
                <div style="max-height: 400px; overflow-y: auto; font-family: sans-serif; font-size: 14px;">
                    <h4 style="margin-top:0;">发现 ${errors.length} 个潜在的变量更新问题：</h4>
                    <ul style="padding-left: 20px; margin-bottom: 0;">
                        ${errors.map(e => `<li style="margin-bottom: 8px;">${e}</li>`).join('')}
                    </ul>
                </div>
            `;
            // 使用 toastr 显示一个不会自动消失的警告消息
            toastr.warning(errorMessage, "变量更新二次检查", {
                timeOut: 20000, // 20秒后自动消失
                extendedTimeOut: 10000,
                closeButton: true,
                tapToDismiss: false,
                "preventDuplicates": true,
            });
        }
    }

    /**
     * 事件监听器，当新消息接收时触发校验
     * @param {number} message_id - 新消息的ID
     */
    function onMessageReceived(message_id) {
        try {
            // 获取刚刚收到的那条消息
            const messages = getChatMessages(message_id, { include_swipes: false });
            if (messages && messages.length > 0) {
                validateVariableUpdates(messages[0]);
            }
        } catch (error) {
            console.error("【变量更新监视脚本】在处理消息时出错:", error);
            toastr.error("变量更新监视脚本运行时发生错误，详情请查看控制台。", "脚本错误");
        }
    }

    // --- 启动监听 ---
    // 等待 Mvu 初始化完毕再开始监听
    waitGlobalInitialized('Mvu').then(() => {
        // 监听酒馆的消息接收事件
        eventOn(tavern_events.MESSAGE_RECEIVED, onMessageReceived);
    });

})();

/**
 * @name '实时校准'的NPC档案守护者
 * @description 自动校验并修复AI创建新NPC时的数据，确保结构完整和文风提示正确。
 * @version 2.0
 * @author Gemini
 */
(function () {
    if (typeof SillyTavern === 'undefined' || typeof Mvu === 'undefined' || typeof _ === 'undefined') {
        console.error("此脚本依赖 SillyTavern, Mvu 和 lodash API。");
        return;
    }

    // 定义NPC数据的“黄金标准”模板
    const npcGoldenTemplate = {
        "姓名": ["未知", ""],
        "战力层级": ["1(凡人)", ""],
        "等级": [1, ""],
        "种族": ["未知", ""],
        "身份": ["未知", ""],
        "职业": ["未知", ""],
        "性格": ["[请用粗俗、直白的风格描述]", ""],
        "喜爱": ["[请描述]", ""],
        "外貌": ["[请用大胆、露骨的风格描述]", ""],
        "衣着": ["[请描述]", ""],
        "装备": ["无", ""],
        "好感度": [50, ""],
        "评价": ["[请填写对该角色的初步评价]", ""],
        "当前位置": ["未知", ""]
    };

    // 这是一个修正锁，防止在修正数据时触发无限循环
    let isCorrecting = false;

    async function validateAndCorrectNpcData(mvuData) {
        if (isCorrecting || !mvuData || !mvuData.stat_data) return;

        const contacts = _.get(mvuData, 'stat_data.人脉关系[0]', {});
        let corrections = {}; // 存储需要修正的数据

        for (const key in contacts) {
            const npc = contacts[key];
            let needsCorrection = false;
            let correctedNpc = _.cloneDeep(npc);

            // 检查并补完缺失的字段
            for (const templateKey in npcGoldenTemplate) {
                if (!_.has(correctedNpc, templateKey)) {
                    correctedNpc[templateKey] = npcGoldenTemplate[templateKey];
                    needsCorrection = true;
                }
            }

            // 可以在这里添加更多检查，比如检查文风提示

            if (needsCorrection) {
                corrections[key] = correctedNpc;
            }
        }

        if (!_.isEmpty(corrections)) {
            isCorrecting = true; // 上锁
            try {
                let commandString = '';
                for (const key in corrections) {
                    commandString += `_.set('人脉关系[0].${key}', ${JSON.stringify(corrections[key])});\n`;
                }

                const newData = await Mvu.parseMessage(commandString, mvuData);
                if (newData) {
                    await Mvu.replaceMvuData(newData, { type: 'message', message_id: 'latest' });
                    console.log('【NPC档案守护者】已自动修正以下NPC档案:', Object.keys(corrections).join(', '));
                    toastr.info(`已自动补完 ${Object.keys(corrections).length} 个NPC的档案结构。`, "NPC档案守护者");
                }
            } catch (error) {
                console.error("【NPC档案守护者】修正数据时出错:", error);
            } finally {
                isCorrecting = false; // 解锁
            }
        }
    }

    waitGlobalInitialized('Mvu').then(() => {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, validateAndCorrectNpcData);
        console.log("【'实时校准'的NPC档案守护者】已启动并监听变量更新。");
    });

})();

/**
 * @name '有生命'的世界时钟与事件引擎
 * @description 监测游戏时间和关键状态，自动触发世界事件，让世界动态演进。
 * @version 2.0
 * @author Gemini
 */

(function () {
    if (typeof SillyTavern === 'undefined' || typeof Mvu === 'undefined' || typeof toastr === 'undefined' || typeof _ === 'undefined' || typeof getScriptId === 'undefined' || typeof getVariables === 'undefined' || typeof replaceVariables === 'undefined') {
        console.error("此脚本依赖 SillyTavern, Mvu, toastr, lodash 和脚本变量API。");
        return;
    }

    // --- 事件库 ---
    const worldEvents = {
        daily: [ // 每日有几率触发的事件
            { tensionDelta: 0, tensionEvent: "商业传闻", tensionEffect: "一条新的商路似乎带来了机遇。", newsType: "酒馆留言板", newsContent: "有传言说，来自东方的神秘商队带来了罕见的香料和丝绸。", narrative: "【世界动态：空气中似乎飘着一丝异域的香料味，酒馆里的人们在讨论着发财的机会。】" },
            { tensionDelta: 1, tensionEvent: "怪物异动", tensionEffect: "野外的危险正在增加。", newsType: "金狮快讯", newsContent: "【灾害预警】据报告，城外森林中的狼群活动日益频繁，请过往旅客注意安全。", narrative: "【世界动态：夜晚的狼嚎似乎比以往更加凄厉和响亮。】" }
        ],
        tensionThreshold: [ // 当世界张力达到某个阈值时触发的特殊事件
            { threshold: 5, triggered: false, tensionEvent: "全面战争阴云", tensionEffect: "战争一触即发，各地开始征兵。", newsType: "金狮快讯", newsContent: "【军事行动】帝国发布紧急征兵令，所有适龄男性需到兵役处登记。", narrative: "【世界动态：你看到城镇广场上张贴了征兵令，空气仿佛凝固了一般。】" }
        ]
    };

    // 从脚本变量中获取或初始化引擎的持久化状态
    const SCRIPT_ID = getScriptId();
    let engineMeta = getVariables({ type: 'script', script_id: SCRIPT_ID }) || {};
    if(_.isEmpty(engineMeta)) {
        engineMeta = { lastCheckedDay: -1, triggeredTensionEvents: [] };
        replaceVariables(engineMeta, { type: 'script', script_id: SCRIPT_ID });
    }

    // 解析时间字符串，只获取“日”
    function getDayFromTimeString(timeString) {
        if (typeof timeString !== 'string') return -1;
        const match = timeString.match(/(\d+)日/);
        return match ? parseInt(match[1], 10) : -1;
    }

    async function worldClockTick(mvuData) {
        if (!mvuData || !mvuData.stat_data) return;

        let commandsToExecute = '';
        let narrativeToInject = '';
        let eventTriggered = false;

        const currentTimeString = _.get(mvuData, 'stat_data.世界.时间[0]');
        const currentDay = getDayFromTimeString(currentTimeString);

        // 1. 时间流逝触发器
        if (currentDay !== -1 && currentDay !== engineMeta.lastCheckedDay) {
            engineMeta.lastCheckedDay = currentDay;
            if (Math.random() < 0.25) { // 25%的每日事件触发率
                const event = _.sample(worldEvents.daily);
                if (event) {
                    commandsToExecute += `_.add('世界.世界张力[0].威胁等级[0]', ${event.tensionDelta});\n`;
                    commandsToExecute += `_.set('世界.世界张行[0].事件', '${event.tensionEvent}');\n`;
                    const oldNews = _.get(mvuData.stat_data, `今日新闻.${event.newsType}[0]`, "");
                    const newNews = oldNews.includes("（无）") ? event.newsContent : `${oldNews}\\n${event.newsContent}`;
                    commandsToExecute += `_.set('今日新闻.${event.newsType}[0]', \`${newNews}\`);\n`;
                    narrativeToInject = event.narrative;
                    eventTriggered = true;
                    toastr.info(`每日事件已触发：${event.tensionEvent}`, "世界时钟");
                }
            }
        }

        // 2. 状态阈值触发器（可以扩展更多）
        const currentTension = _.get(mvuData, 'stat_data.世界.世界张力[0].威胁等级[0]', 0);
        for(const event of worldEvents.tensionThreshold) {
            if (currentTension >= event.threshold && !engineMeta.triggeredTensionEvents.includes(event.tensionEvent)) {
                 commandsToExecute += `_.set('世界.世界张力[0].事件', '${event.tensionEvent}');\n`;
                 // ... (添加新闻等更新)
                 narrativeToInject = event.narrative;
                 engineMeta.triggeredTensionEvents.push(event.tensionEvent);
                 eventTriggered = true;
                 toastr.warning(`关键事件已触发：${event.tensionEvent}`, "世界时钟");
                 break; // 每次只触发一个阈值事件
            }
        }

        // 3. 如果有事件被触发，则执行更新
        if (eventTriggered) {
            try {
                const newData = await Mvu.parseMessage(commandsToExecute, mvuData);
                if (newData) {
                    await Mvu.replaceMvuData(newData, { type: 'message', message_id: 'latest' });
                    if (narrativeToInject) {
                        await createChatMessages([{ role: 'system', message: narrativeToInject }]);
                    }
                }
            } catch (error) {
                 console.error("【世界时钟脚本】执行事件时出错:", error);
            }
        }

        // 4. 保存引擎的持久化状态
        await replaceVariables(engineMeta, { type: 'script', script_id: SCRIPT_ID });
    }

    waitGlobalInitialized('Mvu').then(() => {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, worldClockTick);
        console.log("【'有生命'的世界时钟与事件引擎】已启动并监听变量更新。");
    });

})();

/**
 * @name '机遇驱动'的红线缔结助手
 * @description 当非红线角色好感度达到阈值时，自动出现缔结按钮，一键完成绑定。
 * @version 2.0
 * @author Gemini
 */

(function () {
    if (typeof SillyTavern === 'undefined' || typeof Mvu === 'undefined' || typeof toastr === 'undefined' || typeof _ === 'undefined' || typeof getScriptButtons === 'undefined' || typeof replaceScriptButtons === 'undefined') {
        console.error("此脚本依赖 SillyTavern, Mvu, toastr, lodash, และ get/replaceScriptButtons API。");
        return;
    }

    const BIND_THRESHOLD = 500; // 好感度阈值，可自定义
    let activeOpportunities = new Set(); // 存储当前已生成的缔结按钮的角色key

    // 核心函数：检查并更新缔结机会按钮
    async function checkAndDisplayBindOpportunities() {
        try {
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            if (!mvuData || !mvuData.stat_data) return;

            const contacts = _.get(mvuData, 'stat_data.人脉关系[0]', {});
            const redLineChars = _.get(mvuData, 'stat_data.命运系统.红线对象[0]', {});
            const redLineKeys = new Set(Object.keys(redLineChars));

            const currentOpportunities = new Set();

            // 1. 扫描所有“人脉”，寻找新的机会
            for (const key in contacts) {
                const contact = contacts[key];
                const favor = _.get(contact, '好感度[0]', 0);

                if (favor >= BIND_THRESHOLD && !redLineKeys.has(key)) {
                    currentOpportunities.add(key);
                }
            }

            // 2. 如果机会列表没有变化，则不执行任何UI操作
            if (_.isEqual(activeOpportunities, currentOpportunities)) {
                return;
            }

            // 3. 更新按钮
            let currentButtons = getScriptButtons().filter(btn => !btn.name.startsWith('[❤️ 缔结红线:'));

            currentOpportunities.forEach(key => {
                const characterName = _.get(contacts[key], '姓名[0]');
                if (characterName) {
                    const buttonName = `[❤️ 缔结红线: ${characterName}]`;
                    currentButtons.push({ name: buttonName, visible: true });

                    // 为新出现的按钮动态绑定一次性点击事件
                    if (!activeOpportunities.has(key)) {
                        eventOnce(getButtonEvent(buttonName), () => handleBindExecution(key, characterName));
                    }
                }
            });

            replaceScriptButtons(currentButtons);
            activeOpportunities = currentOpportunities;

        } catch (error) {
            console.error("【红线缔结助手】检查时出错:", error);
        }
    }

    // 执行绑定的函数
    async function handleBindExecution(characterKey, characterName) {
        try {
            toastr.info(`正在将 ${characterName} 缔结为红线对象...`);
            const mvuData = Mvu.getMvuData({ type: 'message', message_id: 'latest' });
            const characterData = _.get(mvuData, `stat_data.人脉关系[0].${characterKey}`);

            if (!characterData) {
                toastr.error(`操作失败：无法再次找到 ${characterName} 的数据。`);
                return;
            }

            const newRedLineCharacter = _.cloneDeep(characterData);
            _.set(newRedLineCharacter, '记忆回廊', [{ "$meta": { "extensible": true } }]);
            _.set(newRedLineCharacter, '日程表', ["", ""]);

            const assignCommand = `_.assign('命运系统.红线对象[0]', '${characterKey}', ${JSON.stringify(newRedLineCharacter)});`;
            const removeCommand = `_.remove('人脉关系[0]', '${characterKey}');`;

            const newData = await Mvu.parseMessage(`${assignCommand}\n${removeCommand}`, mvuData);

            if (newData) {
                await Mvu.replaceMvuData(newData, { type: 'message', message_id: 'latest' });
                await createChatMessages([{ role: 'system', message: `【系统：你与 ${characterName} 的命运被红线紧密地连接在了一起。】`, is_hidden: true }]);
                toastr.success(`成功将 ${characterName} 缔结为红线对象！`);
            }
        } catch (error) {
            console.error("【红线缔结脚本】执行绑定时出错:", error);
            toastr.error(`缔结 ${characterName} 时发生内部错误。`);
        }
    }

    // 启动监听
    waitGlobalInitialized('Mvu').then(() => {
        eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, checkAndDisplayBindOpportunities);
        console.log("【'机遇驱动'的红线缔结助手】已启动并监听变量更新。");
    });
})();

